def clean(df):
    d = df.copy()
    d = d.drop_duplicates()
    if 'Order_ID' in d.columns:
        d = d.drop_duplicates(subset=['Order_ID'], keep='first')
    if 'Region' in d.columns:
        d['Region'] = d['Region'].astype(str).str.strip().replace({'Nort': 'North'})
    for col in ['Quantity', 'Price', 'Revenue']:
        if col in d.columns:
            d[col] = pd.to_numeric(d[col], errors='coerce')
    if 'Quantity' in d.columns:
        d['Quantity'] = d['Quantity'].abs()
    if all(col in d.columns for col in ['Quantity', 'Price', 'Revenue']):
        d['Revenue'] = d['Quantity'] * d['Price']
    return d

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['Region', 'Quantity'])
    grouped = d.groupby('Region', dropna=True)['Quantity'].sum()
    result = {}
    for key, value in grouped.items():
        value = float(value)
        result[str(key)] = int(value) if value.is_integer() else value
    return result
